mapper.select:


    p.del_flag = '0'

        and p.title like concat('%', #{title}, '%')


        and p.category = #{category}


        and p.channel = #{channel}


        and p.status = #{status}


        and p.warn_level = #{warnLevel}


        and p.anonymous_flag = #{anonymousFlag}


        and p.target_name like concat('%', #{targetName}, '%')


        and date_format(p.create_time, '%Y%m%d') >= date_format(#{params.beginTime}, '%Y%m%d')


        and date_format(p.create_time, '%Y%m%d') <= date_format(#{params.endTime}, '%Y%m%d')


order by
    case when p.status in ('6','7') then 1 else 0 end,
    case p.warn_level when '红灯' then 0 when '黄灯' then 1 else 2 end,
    p.handle_deadline asc,
    p.create_time desc

mapper.insert:
insert into jc_petition (
receipt_lookup, receipt_hash, title, content, channel, category, anonymous_flag, reporter_name, reporter_phone, reporter_idcard, target_name, target_dept, amount, status, warn_level, handle_deadline, feedback, remark, create_by, create_time
) values (
#{receiptLookup}, #{receiptHash}, #{title}, #{content}, #{channel}, #{category}, #{anonymousFlag}, #{reporterName}, #{reporterPhone}, #{reporterIdcard}, #{targetName}, #{targetDept}, #{amount}, #{status}, #{warnLevel}, #{handleDeadline}, #{feedback}, #{remark}, #{createBy}, sysdate()
)

mapper.update:
update jc_petition
status = #{status}, warn_level = #{warnLevel}, handle_deadline = #{handleDeadline}, clue_id = #{clueId}, feedback = #{feedback}, remark = #{remark}, update_by = #{updateBy}, update_time = sysdate()
where petition_id = #{petitionId}

mapper.select:

where p.del_flag = '0' and p.target_name = #{targetName}
  and p.create_time >= #{since} and p.status <> '7'
order by p.create_time desc
